import { createRequire } from 'node:module';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { writeFile } from 'node:fs/promises';

const root = '/home/kernel-kain/Documents/Github/chesspulse';
const require = createRequire(path.join(root, 'package.json'));
const { app, BrowserWindow, ipcMain } = require('electron');
const { BetweenGamesCoach } = require(path.join(root, 'dist-electron/main/coach.js'));
const { coachGapRequestSchema, coachMessageSchema } = require(path.join(root, 'dist-electron/shared/contracts.js'));
const START_US = 1_000_000;
let coach = null;
let win = null;

function sample(offsetUs, bpm, confidence = 80) {
  return { tUs: START_US + offsetUs, bpm, confidence, stable: true };
}

function publishCoach(message) {
  if (message) win.webContents.send('cp:coach:message', coachMessageSchema.parse(message));
}

function publishBatch(samples) {
  win.webContents.send('cp:sample:batch', samples);
  publishCoach(coach.ingest(samples));
}

async function waitFor(expression) {
  const deadline = Date.now() + 3000;
  while (Date.now() < deadline) {
    if (await win.webContents.executeJavaScript(expression, true)) return;
    await new Promise((resolve) => setTimeout(resolve, 20));
  }
  throw new Error(`Timed out waiting for: ${expression}`);
}

app.whenReady().then(async () => {
  ipcMain.handle('cp:consent:set', (_event, payload) => ({ granted: payload.granted, cameraAllowed: payload.granted }));
  ipcMain.handle('cp:session:start', () => {
    coach = new BetweenGamesCoach(START_US);
    return { sessionId: 'coach-smoke' };
  });
  ipcMain.handle('cp:coach:gap', (_event, payload) => {
    const parsed = coachGapRequestSchema.parse(payload);
    publishCoach(coach.setBetweenGames(parsed.betweenGames));
    return parsed;
  });

  win = new BrowserWindow({
    show: false,
    width: 1100,
    height: 760,
    webPreferences: {
      preload: path.join(root, 'dist-electron/preload/index.js'),
      contextIsolation: true,
      sandbox: true,
      nodeIntegration: false,
    },
  });
  await win.loadURL(pathToFileURL(path.join(root, 'dist/index.html')).href);

  await win.webContents.executeJavaScript(`[...document.querySelectorAll('button')].find((b) => b.textContent === 'Allow the camera').click()`, true);
  await waitFor(`[...document.querySelectorAll('button')].some((b) => b.textContent === 'Start sensing' && !b.disabled)`);
  await win.webContents.executeJavaScript(`[...document.querySelectorAll('button')].find((b) => b.textContent === 'Start sensing').click()`, true);
  await waitFor(`[...document.querySelectorAll('button')].some((b) => b.textContent === 'Game ended')`);

  publishBatch([sample(0, 70), sample(30_000_000, 70), sample(59_000_000, 70)]);
  await win.webContents.executeJavaScript(`[...document.querySelectorAll('button')].find((b) => b.textContent === 'Game ended').click()`, true);
  await waitFor(`document.querySelector('.coach-quiet')?.textContent === 'Nothing to say yet.'`);

  publishBatch([sample(60_000_000, 90), sample(61_000_000, 90), sample(62_000_000, 90)]);
  await waitFor(`document.querySelector('.coach-message')?.textContent.includes('Pulse still +20 over baseline')`);
  const first = await win.webContents.executeJavaScript(`({
    messages: document.querySelectorAll('.coach-message').length,
    numbers: document.querySelector('.coach-numbers')?.textContent,
    button: [...document.querySelectorAll('button')].find((b) => b.textContent === 'Next game started')?.textContent
  })`, true);

  const image = await win.webContents.capturePage();
  await writeFile(path.join(root, 'docs/images/s22-coach-synthetic.png'), image.toPNG());

  publishBatch([sample(63_000_000, 91)]);
  await waitFor(`document.querySelector('.strip .live')?.textContent.includes('91 bpm')`);
  const repeated = await win.webContents.executeJavaScript(`document.querySelectorAll('.coach-message').length`, true);

  await win.webContents.executeJavaScript(`[...document.querySelectorAll('button')].find((b) => b.textContent === 'Next game started').click()`, true);
  await waitFor(`!document.querySelector('.coach-panel') && [...document.querySelectorAll('button')].some((b) => b.textContent === 'Game ended')`);
  const hiddenDuringPlay = await win.webContents.executeJavaScript(`!document.querySelector('.coach-panel')`, true);

  await win.webContents.executeJavaScript(`[...document.querySelectorAll('button')].find((b) => b.textContent === 'Game ended').click()`, true);
  await waitFor(`document.querySelector('.coach-message')?.textContent.includes('Pulse still +')`);
  const secondGap = await win.webContents.executeJavaScript(`document.querySelectorAll('.coach-message').length`, true);
  const invalid = await win.webContents.executeJavaScript(`window.chesspulse.setBetweenGames('yes').then(() => 'accepted', (error) => error.message)`, true);

  const ok = first.messages === 1 && first.numbers.includes('Baseline 70 bpm') && first.numbers.includes('Last-minute median 90 bpm') && repeated === 1 && hiddenDuringPlay && secondGap === 1 && invalid === 'The game boundary must be between games or playing.';
  console.log(JSON.stringify({ first, repeated, hiddenDuringPlay, secondGap, invalid, ok }));
  app.exit(ok ? 0 : 1);
}).catch((error) => {
  console.error(error instanceof Error ? error.stack : error);
  app.exit(1);
});

