8:   | { found: false; path: string };
9: 
10: const KEY = /^[A-Z_][A-Z0-9_]*$/;
11: 
12: export function loadEnvFile(filePath: string, env: NodeJS.ProcessEnv): EnvLoadResult {
13:   let text: string;
14:   try {
15:     text = readFileSync(filePath, 'utf8');
16:   } catch {
17:     return { found: false, path: filePath };
18:   }
19:   const loadedKeys: string[] = [];
20:   for (const rawLine of text.split(/\r?\n/)) {
21:     const line = rawLine.trim();
22:     if (line === '' || line.startsWith('#')) continue;
23:     const body = line.startsWith('export ') ? line.slice('export '.length).trim() : line;
24:     const equals = body.indexOf('=');
25:     if (equals <= 0) continue;
26:     const key = body.slice(0, equals).trim();
27:     if (!KEY.test(key)) continue;
28:     // A value already exported by the shell wins over the file.
29:     if (env[key] !== undefined && env[key] !== '') continue;
30:     env[key] = unquote(body.slice(equals + 1).trim());
31:     loadedKeys.push(key);
32:   }
33:   return { found: true, path: filePath, loadedKeys };
34: }
35: 
36: export function readSensingKey(env: NodeJS.ProcessEnv): string {
37:   const value = env.SMARTSPECTRA_API_KEY;
38:   return typeof value === 'string' && value.trim().length > 0 ? value.trim() : '';
39: }
