import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { describe, it } from 'node:test';
import { groundInsight } from './grounding.js';

interface EvalFixture {
  name: string;
  input: string;
  response: string;
  expected: string;
}

function fixture(name: string): EvalFixture {
  return JSON.parse(readFileSync(path.join(process.cwd(), 'tests/fixtures/ai', `${name}.json`), 'utf8')) as EvalFixture;
}

describe('AI grounding evaluation fixtures', () => {
  for (const name of ['normal', 'ambiguous', 'malformed']) {
    it(`accepts ${name} output without changing it`, () => {
      const item = fixture(name);
      assert.equal(groundInsight(item.input, item.response), item.response);
    });
  }

  it('rejects a number introduced after an adversarial PGN header', () => {
    const item = fixture('adversarial');
    assert.throws(() => groundInsight(item.input, item.response), /introduced a number.*99/);
  });
});

describe('groundInsight', () => {
  it('treats equivalent number formatting as grounded', () => {
    assert.equal(groundInsight('Accuracy 71.0%; 1,200 moves.', 'Accuracy 71% across 1200 moves.'), 'Accuracy 71% across 1200 moves.');
  });

  it('rejects percentages, signed values, and decimals absent from the payload', () => {
    assert.throws(() => groundInsight('Baseline 70.', 'Baseline 70; accuracy 54%.'), /54/);
    assert.throws(() => groundInsight('Baseline 70.', 'Pulse +18.5 above baseline.'), /18\.5/);
  });
});

