  const fixture = JSON.parse(
    readFileSync(path.join(process.cwd(), 'tests/fixtures/ai/provider-failure.json'), 'utf8'),
  ) as { sequence: string[] };
  let calls = 0;
  await assert.rejects(
    requestInsight(REQUEST, ENV, {
