            }),
          } as Response;
        },
      }),
      /timed out/,
    );
    assert.equal(calls, 1);
  });

  it('stops after the provider-failure fixture retries once and times out', async () => {
    const fixture = JSON.parse(
      readFileSync(path.join(process.cwd(), 'tests/fixtures/ai/provider-failure.json'), 'utf8'),
    ) as { sequence: string[] };
    let calls = 0;
