import { createRequire } from 'node:module';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { mkdtempSync, readFileSync } from 'node:fs';
import { writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';

const root = '/home/kernel-kain/Documents/Github/chesspulse';
const require = createRequire(path.join(root, 'package.json'));
const { app, BrowserWindow, ipcMain } = require('electron');
const { createSession, saveReport, saveGames } = require(path.join(root, 'dist-electron/main/store.js'));
const { registerInsightHandler } = require(path.join(root, 'dist-electron/main/insight-ipc.js'));
const { registerPasteHandler } = require(path.join(root, 'dist-electron/main/paste.js'));
const dataRoot = mkdtempSync(path.join(tmpdir(), 'chesspulse-insight-e2e-'));
const env = {};
let mode = 'ready';
let calls = 0;
let aborted = false;
let win;

const report = {
  ok: true,
  sessionId: '',
  coveragePct: 80,
  baselineBpm: 70,
  verdict: 'Accuracy 71% settled.',
  settled: { band: 'settled', moves: 5, status: 'ok', accuracy: 71 },
  elevated: { band: 'elevated', moves: 0, status: 'insufficient' },
  alignmentMode: 'endtime',
  toleranceSec: 1,
  games: [],
  timeline: { startUs: 0, stopUs: 1000, baselineBpm: 70, elevatedThresholdBpm: 80, samples: [], games: [], moves: [] },
};

globalThis.fetch = async (_url, init) => {
  calls += 1;
  if (mode === 'error') return new Response('failure', { status: 500 });
  if (mode === 'stall') {
    return new Promise((_resolve, reject) => {
      init?.signal?.addEventListener('abort', () => {
        aborted = true;
        reject(new DOMException('Cancelled', 'AbortError'));
      });
    });
  }
  return new Response(JSON.stringify({ choices: [{ message: { content: 'The accuracy was 71%. <img src=x onerror="window.__htmlRan=true"> <script>window.__scriptRan=true</script>' } }] }), { status: 200 });
};

async function waitFor(expression) {
  const deadline = Date.now() + 4000;
  while (Date.now() < deadline) {
    if (await win.webContents.executeJavaScript(expression, true)) return;
    await new Promise((resolve) => setTimeout(resolve, 20));
  }
  throw new Error(`Timed out waiting for: ${expression}`);
}

async function click(text) {
  await win.webContents.executeJavaScript(`[...document.querySelectorAll('button')].find((b) => b.textContent === ${JSON.stringify(text)}).click()`, true);
}

app.whenReady().then(async () => {
  const meta = await createSession(dataRoot, { startedAtEpochMs: 1700000000000, startAnchor: { monoUs: 0, epochMs: 1700000000000 } });
  report.sessionId = meta.id;
  const pgn = readFileSync(path.join(root, 'tests/fixtures/pgn/checkmate.pgn'), 'utf8');
  await saveReport(dataRoot, meta.id, JSON.stringify(report));
  await saveGames(dataRoot, meta.id, [pgn]);

  ipcMain.handle('cp:consent:set', (_event, payload) => ({ granted: payload.granted, cameraAllowed: payload.granted }));
  ipcMain.handle('cp:session:start', () => ({ sessionId: meta.id }));
  ipcMain.handle('cp:session:stop', () => ({
    ...meta,
    baselineBpm: 70,
    stopReason: 'user',
    stopAnchor: { monoUs: 1000, epochMs: 1700000000001 },
    coverage: { usableUs: 1000, totalUs: 1000, pct: 100, confidenceFloor: 50 },
  }));
  ipcMain.handle('cp:report:build', () => report);
  registerPasteHandler();
  registerInsightHandler(() => dataRoot, env);

  win = new BrowserWindow({
    show: false,
    width: 1100,
    height: 850,
    webPreferences: {
      preload: path.join(root, 'dist-electron/preload/index.js'),
      contextIsolation: true,
      sandbox: true,
      nodeIntegration: false,
    },
  });
  await win.loadURL(pathToFileURL(path.join(root, 'dist/index.html')).href);

  await click('Allow the camera');
  await waitFor(`[...document.querySelectorAll('button')].some((b) => b.textContent === 'Start sensing' && !b.disabled)`);
  await click('Start sensing');
  await waitFor(`[...document.querySelectorAll('button')].some((b) => b.textContent === 'Stop sensing')`);
  await click('Stop sensing');
  await waitFor(`[...document.querySelectorAll('button')].some((b) => b.textContent === 'Paste PGNs')`);
  await click('Paste PGNs');
  await win.webContents.executeJavaScript(`(() => {
    const area = document.querySelector('textarea');
    const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
    setter.call(area, ${JSON.stringify(pgn)});
    area.dispatchEvent(new Event('input', { bubbles: true }));
  })()`, true);
  await waitFor(`[...document.querySelectorAll('button')].some((b) => b.textContent === 'Continue to report' && !b.disabled)`);
  await click('Continue to report');
  await waitFor(`!!document.querySelector('.insight-panel')`);
  const noAutoCall = calls === 0;
  const inferred = await win.webContents.executeJavaScript(`document.querySelector('.inferred-label').textContent`, true);

  await click('Write reading');
  await waitFor(`document.querySelector('[role="status"]')?.textContent.includes('No AI key configured')`);
  const keylessCalls = calls;

  env.CP_AI_KEY = 'test-secret';
  env.CP_AI_MODEL = 'test-model';
  mode = 'error';
  await click('Write reading');
  await waitFor(`document.querySelector('.insight-error')?.textContent.includes('provider is unavailable')`);
  const errorCalls = calls;
  const reportIntact = await win.webContents.executeJavaScript(`document.querySelector('.verdict-line')?.textContent === 'Accuracy 71% settled.'`, true);

  mode = 'stall';
  await click('Write reading');
  await waitFor(`[...document.querySelectorAll('button')].some((b) => b.textContent === 'Cancel')`);
  await click('Cancel');
  await waitFor(`document.querySelector('.insight-note')?.textContent.includes('Nothing is sent')`);
  const cancelled = aborted;

  mode = 'ready';
  await click('Write reading');
  await waitFor(`document.querySelector('.insight-text')?.textContent.includes('The accuracy was 71%')`);
  const html = await win.webContents.executeJavaScript(`({
    text: document.querySelector('.insight-text').textContent,
    images: document.querySelectorAll('.insight-panel img').length,
    scripts: document.querySelectorAll('.insight-panel script').length,
    htmlRan: window.__htmlRan === true,
    scriptRan: window.__scriptRan === true
  })`, true);
  await win.webContents.executeJavaScript(`document.querySelector('.insight-panel').scrollIntoView({ block: 'center' })`, true);
  const image = await win.webContents.capturePage();
  await writeFile(path.join(root, 'docs/images/s24-inferred-synthetic.png'), image.toPNG());

  win.setSize(640, 900);
  const narrow = await win.webContents.executeJavaScript(`({ overflow: document.documentElement.scrollWidth > 640, panelOrder: getComputedStyle(document.querySelector('.insight-panel')).order })`, true);
  const ok = noAutoCall && inferred.startsWith('INFERRED') && keylessCalls === 0 && errorCalls === 2 && reportIntact && cancelled && html.text.includes('<img') && html.text.includes('<script>') && html.images === 0 && html.scripts === 0 && !html.htmlRan && !html.scriptRan && !narrow.overflow && narrow.panelOrder === '5';
  console.log(JSON.stringify({ noAutoCall, inferred, keylessCalls, errorCalls, reportIntact, cancelled, html, narrow, ok }));
  app.exit(ok ? 0 : 1);
}).catch((error) => {
  console.error(error instanceof Error ? error.stack : error);
  app.exit(1);
});

