1: // What: rejects model-written numbers absent from structured, locally computed statistics.
2: // Why: PGN text is untrusted and cannot be allowed to forge a computed-data marker.
3: // Removed: injected PGN numbers, leading-dot decimals, and rounded large integers could pass as grounded.
4: const NUMBER = /[-+]?(?:\d[\d,]*(?:\.\d*)?|\.\d[\d,]*)(?:[eE][-+]?\d+)?/g;
5: const VALID_COMMA_NUMBER = /^[-+]?(?:\d+(?:,\d{3})*(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/;
6: 
7: export function groundInsight(stats: unknown, output: string): string {
8:   for (const match of output.matchAll(NUMBER)) {
9:     if (match[0].includes(',') && !VALID_COMMA_NUMBER.test(match[0])) {
10:       throw new Error(`The AI response contained a malformed number: ${match[0]}. Nothing in the report changed.`);
11:     }
12:   }
13:   const serialized = JSON.stringify(stats, (_key, value) => (typeof value === 'bigint' ? value.toString() : value)) ?? '';
14:   const allowed = new Set([...serialized.matchAll(NUMBER)].map((match) => canonicalDecimal(match[0])));
15:   for (const match of output.matchAll(NUMBER)) {
16:     const token = match[0];
17:     if (!allowed.has(canonicalDecimal(token))) {
18:       throw new Error(`The AI response introduced a number that is not in the session data: ${token}. Nothing in the report changed.`);
19:     }
20:   }
21:   return output;
22: }
23: 
24: /** Canonical sign/significant-digits/exponent comparison avoids IEEE-754 rounding. */
25: function canonicalDecimal(token: string): string {
26:   let text = token.replaceAll(',', '');
27:   let sign = '';
28:   if (text.startsWith('+') || text.startsWith('-')) {
29:     sign = text[0] === '-' ? '-' : '';
30:     text = text.slice(1);
31:   }
32:   const [mantissa, exponentText] = text.split(/[eE]/);
33:   const dot = mantissa.indexOf('.');
34:   const fractionDigits = dot < 0 ? 0 : mantissa.length - dot - 1;
35:   let digits = mantissa.replace('.', '').replace(/^0+/, '');
36:   if (!digits) return '0';
37:   const trailingZeros = digits.match(/0+$/)?.[0].length ?? 0;
38:   digits = digits.slice(0, digits.length - trailingZeros);
39:   const scale = BigInt(exponentText ?? '0') - BigInt(fractionDigits) + BigInt(trailingZeros);
40:   return `${sign}${digits}e${scale.toString()}`;
41: }

