1: // What: serves optional AI readings from the stored report and original PGNs.
2: // Why: the renderer never supplies grounding statistics, and one session has at most one active call.
3: // Removed: a stale or forged renderer payload could reach a provider without cancellation or an audit id.
4: import { randomUUID } from 'node:crypto';
5: import { ipcMain } from 'electron';
6: import {
7:   insightCancelRequestSchema,
8:   insightRequestSchema,
9:   insightResultSchema,
10: } from '../shared/contracts.js';
11: import { requestInsight } from './ai/service.js';
12: import { log, logError } from './log.js';
13: import { defaultDataRoot, readGames, readReport } from './store.js';
14: 
15: export const INSIGHT_REQUEST_CHANNEL = 'cp:insight:request';
16: export const INSIGHT_CANCEL_CHANNEL = 'cp:insight:cancel';
17: 
18: export function registerInsightHandler(dataRoot: () => string = defaultDataRoot, env: NodeJS.ProcessEnv = process.env): void {
19:   const active = new Map<string, AbortController>();
20: 
21:   ipcMain.handle(INSIGHT_REQUEST_CHANNEL, async (_event, payload: unknown) => {
22:     const parsed = insightRequestSchema.safeParse(payload);
23:     if (!parsed.success) throw new Error('Choose a session, provider, and question under 4 KB.');
24:     if (active.has(parsed.data.sessionId)) throw new Error('An AI reading is already running for this session.');
25:     const requestId = randomUUID();
26:     const controller = new AbortController();
27:     active.set(parsed.data.sessionId, controller);
28:     try {
29:       const report = await readReport(dataRoot(), parsed.data.sessionId);
30:       const pgns = await readGames(dataRoot(), parsed.data.sessionId);
31:       const result = insightResultSchema.parse(
32:         await requestInsight(parsed.data, report, pgns, env, { signal: controller.signal }),
33:       );
34:       log(`[chesspulse] AI reading ${requestId} ${result.disabled ? 'disabled' : 'ready'}`);
35:       return result;
36:     } catch (error) {
37:       logError(`[chesspulse] AI reading ${requestId} failed`);
38:       throw error;
39:     } finally {
40:       if (active.get(parsed.data.sessionId) === controller) active.delete(parsed.data.sessionId);
41:     }
42:   });
43: 
44:   ipcMain.handle(INSIGHT_CANCEL_CHANNEL, (_event, payload: unknown) => {
45:     const parsed = insightCancelRequestSchema.safeParse(payload);
46:     if (!parsed.success) throw new Error('Choose a session to cancel.');
47:     const controller = active.get(parsed.data.sessionId);
48:     controller?.abort();
49:     return { cancelled: controller !== undefined };
50:   });
51: }

