10: 
11: export function registerReportHandler(dataRoot: () => string = defaultDataRoot): void {
12:   // Serialize builds so concurrent IPC calls do not race on report.json or spawn overlapping Stockfish workers.
13:   let queue: Promise<unknown> = Promise.resolve();
14:   ipcMain.handle(REPORT_BUILD_CHANNEL, async (_event, payload: unknown) => {
