30:     text = text.slice(1);
31:   }
32:   const [mantissa, exponentText] = text.split(/[eE]/);
33:   const dot = mantissa.indexOf('.');
34:   const fractionDigits = dot < 0 ? 0 : mantissa.length - dot - 1;
35:   let digits = mantissa.replace('.', '').replace(/^0+/, '');
36:   if (!digits) return '0';
37:   const trailingZeros = digits.match(/0+$/)?.[0].length ?? 0;
38:   digits = digits.slice(0, digits.length - trailingZeros);
39:   const scale = BigInt(exponentText ?? '0') - BigInt(fractionDigits) + BigInt(trailingZeros);
40:   return `${sign}${digits}e${scale.toString()}`;
41: }

