3: import type { PulseSample } from '../shared/contracts.js';
4: import { BetweenGamesCoach } from './coach.js';
5: 
6: const START_US = 1_000_000;
7: 
8: function sample(tUs: number, bpm: number, confidence = 80, stable = true): PulseSample {
9:   return { tUs: START_US + tUs, bpm, confidence, stable };
10: }
11: 
12: function restingMinute(): PulseSample[] {
13:   return [sample(0, 70), sample(30_000_000, 70), sample(59_000_000, 70)];
14: }
15: 
16: describe('BetweenGamesCoach', () => {
17:   it('stays silent during a game and until the first baseline minute is complete', () => {
18:     const coach = new BetweenGamesCoach(START_US);
19:     assert.equal(coach.ingest([...restingMinute(), sample(61_000_000, 90)]), null);
20: 
21:     assert.equal(coach.setBetweenGames(true), null);
22:     const early = new BetweenGamesCoach(START_US);
23:     early.setBetweenGames(true);
24:     assert.equal(early.ingest([sample(0, 70), sample(30_000_000, 90)]), null);
25:   });
26: 
27:   it('fires at baseline plus 10 using the trailing-minute median and shows the numbers', () => {
28:     const coach = new BetweenGamesCoach(START_US);
29:     coach.ingest(restingMinute());
30:     coach.setBetweenGames(true);
31: 
32:     assert.deepEqual(coach.ingest([sample(61_000_000, 80), sample(62_000_000, 90), sample(63_000_000, 80)]), {
33:       baselineBpm: 70,
34:       recentBpm: 80,
35:       deltaBpm: 10,
36:       text: 'Pulse still +10 over baseline. Take a real break before the next game.',
37:     });
38:   });
39: 
40:   it('does not let weak or unstable samples create a coach line', () => {
41:     const weak = new BetweenGamesCoach(START_US);
42:     weak.ingest(restingMinute());
43:     weak.setBetweenGames(true);
44:     // The baseline samples are outside this trailing window, so an unfiltered 95 would fire.
45:     assert.equal(weak.ingest([sample(121_000_000, 95, 10)]), null);
46: 
47:     const unstable = new BetweenGamesCoach(START_US);
48:     unstable.ingest(restingMinute());
49:     unstable.setBetweenGames(true);
50:     assert.equal(unstable.ingest([sample(121_000_000, 95, 80, false)]), null);
51:   });
52: 
53:   it('fires once per gap and clears the latch for the next gap only', () => {
54:     const coach = new BetweenGamesCoach(START_US);
55:     coach.ingest(restingMinute());
56:     coach.setBetweenGames(true);
57: 
58:     assert.notEqual(
59:       coach.ingest([sample(60_000_000, 90), sample(61_000_000, 90), sample(62_000_000, 90)]),
60:       null,
61:     );
62:     assert.equal(coach.ingest([sample(63_000_000, 91)]), null);
63:     assert.equal(coach.setBetweenGames(true), null);
64: 
65:     coach.setBetweenGames(false);
66:     assert.notEqual(coach.setBetweenGames(true), null);
67:     assert.equal(coach.ingest([sample(64_000_000, 92)]), null);
68:   });
69: });

